```
public class ViewTypeDetector extends Detector implements SourceCodeScanner {
    private static final String FIND_VIEW_BY_ID = "findViewById";
    private static final String ANDROID_VIEW_VIEW = "android.view.View";
    private static final String ANDROID_APP_ACTIVITY = "android.app.Activity";
    private static final String ANDROID_APP_FRAGMENT = "android.app.Fragment";
    private static final String ANDROID_SUPPORT_V4_APP_FRAGMENT = "android.support.v4.app.Fragment";
    private static final String ANDROIDX_FRAGMENT_APP_FRAGMENT = "androidx.fragment.app.Fragment";

    @Override
    public List<String> getApplicableMethodNames() {
        return Collections.singletonList(FIND_VIEW_BY_ID);
    }

    @Override
    public void visitMethodCall(@NotNull JavaContext context, @NotNull UCallExpression node, @NotNull PsiMethod method) {
        if (!context.getFile().getName().endsWith(SdkConstants.DOT_JAVA)) {
            return;
        }

        JavaEvaluator evaluator = context.getEvaluator();
        PsiClass containingClass = method.getContainingClass();
        if (containingClass == null) {
            return;
        }

        if (!evaluator.extendsClass(containingClass, ANDROID_VIEW_VIEW, false) &&
                !evaluator.extendsClass(containingClass, ANDROID_APP_ACTIVITY, false) &&
                !evaluator.extendsClass(containingClass, ANDROID_APP_FRAGMENT, false) &&
                !evaluator.extendsClass(containingClass, ANDROID_SUPPORT_V4_APP_FRAGMENT, false) &&
                !evaluator.extendsClass(containingClass, ANDROIDX_FRAGMENT_APP_FRAGMENT, false)) {
            return;
        }

        if (node.getTypeArguments().length > 0) {
            return;
        }

        if (isCast(node)) {
            return;
        }

        PsiType expectedType = getExpectedType(node);
        if (expectedType == null || PsiType.VOID.equals(expectedType)) {
            return;
        }

        if (!(expectedType instanceof PsiClassType)) {
            return;
        }

        PsiClassType expectedClassType = (PsiClassType) expectedType;
        if (ANDROID_VIEW_VIEW.equals(expectedClassType.getCanonicalText())) {
            return;
        }

        PsiClass expectedClass = expectedClassType.resolve();
        if (expectedClass == null || !evaluator.extendsClass(expectedClass, ANDROID_VIEW_VIEW, false)) {
            return;
        }

        String cast = expectedType.getPresentableText();
        String message = String.format("Add explicit cast to %1$s", cast);
        LintFix fix = fix().name("Cast to " + cast).replace().range(context.getLocation(node)).with("(" + cast + ") " + node.asSourceString()).build();
        context.report(ISSUE, node, context.getLocation(node), message, fix);
    }

    private static boolean isCast(UExpression node) {
        UElement parent = node.getUastParent();
        while (parent instanceof UParenthesizedExpression) {
            parent = parent.getUastParent();
        }
        return parent instanceof UBinaryExpressionWithType;
    }

    @Nullable
    private static PsiType getExpectedType(UExpression node) {
        UElement current = node;
        while (true) {
            UElement parent = current.getUastParent();
            if (parent == null) {
                return null;
            }
            if (parent instanceof UParenthesizedExpression) {
                current = parent;
            } else if (parent instanceof UBinaryExpressionWithType) {
                return null;
            } else if (parent instanceof UBinaryExpression) {
                UBinaryExpression binary = (UBinaryExpression) parent;
                if (binary.getOperator() == UastBinaryOperator.ASSIGN && binary.getRightOperand() == current) {
                    return binary.getLeftOperand().getExpressionType();
                }
                current = parent;
            } else if (parent instanceof UVariable) {
                UVariable variable = (UVariable) parent;
                if (variable.getUastInitializer() == current) {
                    return variable.getType();
                }
                return null;
            } else {
                current = parent;
            }
        }
    }
}
```

